{
  "record_digest": "7cf9c57f73a93ca88347230956abb624fabb385e06c9bb797f0714f6645a1727",
  "proposed": 4,
  "replacements": [
    {
      "field": "/summary",
      "section_digest": "70446f4f33a055f8acd235053d45439e6a95b5c4af8ef52277a28d605e93d885",
      "text": "The grilling board sent a typed answer to its slower expert seat only when the answer marked or opened a decision. Now, the expert weighs every answer that carries a note or free text. The board's map escalation rules can no longer fire for typed answers. Their code remains."
    },
    {
      "field": "/heads_up/0",
      "section_digest": "b55784141f73dc3052e94ee637d014b2d7e791830673436c5f5f2996b661b7f0",
      "text": "Twelve existing tests now use an option pick or run on a thread."
    },
    {
      "field": "/commit/why",
      "section_digest": "6dfb8b693fec4adc74aadfd98208a2aa58c7758b7a25e5c16882d98e3e79d445",
      "text": "A typed answer reached the expert seat only when it marked or opened a decision. A typed note with nothing downstream was read by the fast first seat. That contradicted the spec's seating decision."
    },
    {
      "field": "/commit/verification",
      "section_digest": "6381f832c960298123686c1f8dd7da98ce1967ab9a72cea5258ed75518e6934f",
      "text": "make ci exits 0. make e2e-grillui exits 0 with 97 passed. Six new unit tests cover the change. Four of them failed before it. The map's escalation rules are now unreachable. Their code is not removed. No review round ran."
    }
  ]
}
